# tools/grammar-pages/b1.py - the B1 grammar pages (read by pages.py, which has the helpers C, B, S, T, CARD, FLIP, VOC)

P['43'] = dict(
    line="A pronoun can stand for a whole « my book » or « that one ». <b>Possessive</b>: le mien, la mienne, les miens, les miennes (mine), le tien… (yours), le sien… (his or hers), le nôtre, le vôtre, le leur. <b>Demonstrative</b>: celui, celle, ceux, celles (the one, the ones), never alone: celui-<b>ci</b>, celle-<b>là</b>, celui <b>de</b> Paul, celle <b>que</b> j'aime. Both follow the thing, not the owner.",
    words='',
    steps=[
        dict(tool='agree', title='The pronoun follows the thing owned', sub='Switch the thing: the pronoun changes with it, whoever the owner is.', cols=['un livre', 'une maison', 'des livres', 'des maisons'],
             rows=[dict(forms=['le mien', 'la mienne', 'les miens', 'les miennes'], en='mine'), dict(forms=['le tien', 'la tienne', 'les tiens', 'les tiennes'], en='yours (tu)'),
                   dict(forms=['le sien', 'la sienne', 'les siens', 'les siennes'], en='his or hers'), dict(forms=['le nôtre', 'la nôtre', 'les nôtres', 'les nôtres'], en='ours'),
                   dict(forms=['le vôtre', 'la vôtre', 'les vôtres', 'les vôtres'], en='yours (vous)'), dict(forms=['le leur', 'la leur', 'les leurs', 'les leurs'], en='theirs')]),
        dict(tool='swap', title='Replace the noun', sub='Pick a sentence and tap « Use a pronoun ».', button=['Use a pronoun', 'Back'], legend=[['p', 'the pronoun'], ['x', 'what it replaces']],
             items=[dict(label="C'est ton livre.", en=["It's your book.", "It's yours."], a=T(('s', "C'est", ''), ('o', 'ton livre.', 'x')), b=T(('s', "C'est", ''), ('p', 'le tien.', 'p'))),
                    dict(label='Sa voiture est rouge.', en=['His car is red.', 'His is red.'], a=T(('o', 'Sa voiture', 'x'), ('v', 'est rouge.', '')), b=T(('p', 'La sienne', 'p'), ('v', 'est rouge.', '')), note='voiture is feminine: <b>la sienne</b>, for his or for hers.'),
                    dict(label='Je préfère ce gâteau-ci.', en=['I prefer this cake.', 'I prefer this one.'], a=T(('s', 'Je préfère', ''), ('o', 'ce gâteau-ci.', 'x')), b=T(('s', 'Je préfère', ''), ('p', 'celui-ci.', 'p'))),
                    dict(label='la voiture de Paul', en=["Paul's car", "Paul's (one)"], a=T(('o', 'la voiture', 'x'), ('d', 'de Paul', '')), b=T(('p', 'celle', 'p'), ('d', 'de Paul', '')), note='celle never stands alone: <b>celle de</b> Paul.'),
                    dict(label="Les chaussures que j'aime…", en=['The shoes I like…', 'The ones I like…'], a=T(('o', 'Les chaussures', 'x'), ('q', "que j'aime…", '')), b=T(('p', 'Celles', 'p'), ('q', "que j'aime…", ''))),
                    dict(label='Je pense à mes amis.', en=['I think of my friends.', 'I think of mine.'], a=T(('s', 'Je pense', ''), ('o', 'à mes amis.', 'x')), b=T(('s', 'Je pense', ''), ('p', 'aux miens.', 'p')), note='à + les → <b>aux</b> miens; de + le → <b>du</b> mien.')]),
    ],
    practice=dict(
        choose=[C("Ce n'est pas ton stylo, c'est ___.", "It's not your pen, it's mine.", ['le mien', 'la mienne', 'mon', 'le mon'], 'le mien', 'stylo is masculine.', '<b>le mien</b>.'),
                C('Ma maison est grande, ___ est petite. (ours)', 'My house is big, ours is small.', ['la nôtre', 'le nôtre', 'notre', 'la notre'], 'la nôtre', 'maison is feminine; ours has an accent.', '<b>la nôtre</b>.'),
                C('Paul a perdu ses clés. Il cherche ___.', 'Paul lost his keys. He is looking for his.', ['les siennes', 'les siens', 'la sienne', 'leurs'], 'les siennes', 'clés is feminine plural.', '<b>les siennes</b>.'),
                C('Tu préfères ce pull-ci ou ___ ?', 'Do you prefer this jumper or that one?', ['celui-là', 'celle-là', 'cela', 'ce-là'], 'celui-là', 'pull is masculine.', '<b>celui-là</b>.'),
                C('___ qui parle est mon frère.', 'The one who is speaking is my brother.', ['Celui', 'Ce', 'Celle', 'Cela'], 'Celui', 'A man, then qui.', '<b>Celui qui</b>…'),
                C('Je parle ___ (de + le mien).', "I'm talking about mine.", ['du mien', 'de le mien', 'des miens', 'de mien'], 'du mien', 'de + le…', '<b>du</b> mien.'),
                C('Ces chaussures ? Ce sont ___ de Marie.', "These shoes? They're Marie's.", ['celles', 'ceux', 'celle', 'les siennes de'], 'celles', 'chaussures is feminine plural.', '<b>celles</b> de Marie.')],
        build=[B("No, it's yours. (tu, a book)", ['Non,', "c'est", 'le', 'tien.'], 'ton', 'A pronoun, not an adjective.', "c'est <b>le tien</b>."),
               B('Her house is big, ours is small.', ['Sa', 'maison', 'est grande,', 'la nôtre', 'est petite.'], 'notre', 'ours (a house)…', '<b>la nôtre</b>.'),
               B('this one (a cake)', ['celui-ci'], 'celle-ci', 'gâteau is masculine.', '<b>celui-ci</b>.'),
               B('the ones I like (shoes)', ['celles', 'que', "j'aime"], 'ceux', 'chaussures is feminine plural.', "<b>celles</b> que j'aime."),
               B("Paul's car", ['la', 'voiture', 'de', 'Paul'], "Paul's", 'French says « the car of Paul ».', 'la voiture <b>de</b> Paul.')],
        spot=[S(['Ma voiture est bleue,', 'le sien', 'est rouge.'], 1, 'la sienne', 'voiture is feminine: <b>la sienne</b>.', 'Does it match voiture?'),
              S(['Ce livre', "n'est pas", 'mon.'], 2, 'le mien.', 'Alone, use the pronoun: <b>le mien</b>.', 'Is there a noun after it?'),
              S(['Tu préfères', 'celui', 'ou celui-là ?'], 1, 'celui-ci', 'celui never stands alone: <b>celui-ci</b>.', 'What does celui need?'),
              S(['Je pense', 'à les miens.'], 1, 'aux miens.', 'à + les → <b>aux</b>.', 'Look at à + les.'),
              S(['Nos enfants et', 'les leur', 'jouent ensemble.'], 1, 'les leurs', 'Plural: <b>les leurs</b>.', 'One child or several?')]),
    drill=[["No, it's yours (tu, masc.)", "Non, c'est le tien.", 'The pronoun follows the thing: <b>le tien</b>.'], ['Her house is big, ours is small', 'Sa maison est grande, la nôtre est petite.', 'maison is feminine: <b>la nôtre</b>.'],
           ['this one (masc.)', 'celui-ci', 'celui never alone: <b>celui-ci</b>.'], ['The ones I like (fem. pl.)', "celles que j'aime", '<b>celles que</b> …'],
           ["Paul's (a car)", 'celle de Paul', '<b>celle de</b> + the owner.'], ["They are looking for theirs (keys)", 'Ils cherchent les leurs.', 'Plural thing, several owners: <b>les leurs</b>.']])

P['44'] = dict(
    line="Words for people or things not named exactly. Before a noun: <b>chaque</b> (each, always singular), <b>quelques</b> (a few), <b>plusieurs</b> (several), <b>tout / toute / tous / toutes</b> (all, every: tous les jours, toute la nuit), <b>certains</b>, <b>autre</b>, <b>même</b>. On their own: <b>quelqu'un</b>, <b>quelque chose</b>, <b>chacun</b>, <b>tout</b> (everything), <b>tous</b> (all of them, the s is heard). quelqu'un / quelque chose + <b>de</b> + adjective: quelque chose <b>d'</b>intéressant.",
    words='',
    steps=[
        dict(tool='agree', title='The four forms of tout', sub='Switch the noun: tout follows it.', cols=['masc. singular', 'fem. singular', 'masc. plural', 'fem. plural'],
             rows=[dict(forms=['tout le temps', 'toute la journée', 'tous les jours', 'toutes les semaines'], en=['all the time', 'all day', 'every day', 'every week']),
                   dict(forms=['tout le monde', 'toute la ville', 'tous mes amis', 'toutes mes amies'], en=['everyone', 'the whole town', 'all my friends', 'all my (girl)friends'])]),
        dict(tool='sort', title='Before a noun, or on its own?', sub='Tap the box: does it need a noun after it?',
             boxes=[dict(k='adj', label='+ a noun', sub='chaque jour'), dict(k='pro', label='on its own', sub='chacun')],
             cards=[CARD('chaque', 'adj', '<b>chaque</b> élève: always with a noun.'), CARD('chacun', 'pro', '<b>Chacun</b> a son livre.'), CARD('quelques', 'adj', '<b>quelques</b> amis'),
                    CARD("quelqu'un", 'pro', "<b>Quelqu'un</b> frappe à la porte."), CARD('quelque chose', 'pro', "J'ai <b>quelque chose</b> à dire."), CARD('plusieurs (fois)', 'adj', '<b>plusieurs</b> fois'),
                    CARD('Tout va bien.', 'pro', 'everything: <b>tout</b> on its own.'), CARD('certains (étudiants)', 'adj', '<b>certains</b> étudiants')]),
        dict(tool='flip', en='a', title='quelque chose de… , quelqu\'un de…', sub='Tap a card: an adjective after them needs de.',
             cards=[FLIP('something interesting', "quelque chose d'intéressant", 'de + masc. adjective'), FLIP('someone nice', "quelqu'un de gentil", 'de + adjective'),
                    FLIP('nothing new', 'rien de nouveau', 'the same with rien'), FLIP('nobody important', "personne d'important", 'the same with personne')]),
    ],
    practice=dict(
        choose=[C('___ jour, je prends un café.', 'Every day I have a coffee.', ['Chaque', 'Chacun', 'Tous', 'Toute'], 'Chaque', 'Before a singular noun.', '<b>Chaque</b> jour.'),
                C('Je vais à la piscine ___ les jours.', 'I go to the pool every day.', ['tous', 'tout', 'toutes', 'chaque'], 'tous', 'jours is masculine plural.', '<b>tous</b> les jours.'),
                C("J'ai travaillé ___ la nuit.", 'I worked all night.', ['toute', 'tout', 'toutes', 'tous'], 'toute', 'nuit is feminine.', '<b>toute</b> la nuit.'),
                C('___ a son livre.', 'Each one has his book.', ['Chacun', 'Chaque', 'Tout', 'Quelques'], 'Chacun', 'On its own…', '<b>Chacun</b>.'),
                C("J'ai vu quelque chose ___ bizarre.", 'I saw something strange.', ['de', 'du', 'que', '—'], 'de', 'quelque chose + adjective…', 'quelque chose <b>de</b> bizarre.'),
                C("J'ai invité ___ amis.", 'I invited a few friends.', ['quelques', 'quelque', 'chaque', 'quelqu\'un'], 'quelques', 'a few, plural.', '<b>quelques</b> amis.'),
                C('Ils sont ___ venus.', 'They all came.', ['tous', 'tout', 'toutes', 'chacun'], 'tous', 'all of them (masculine).', 'ils sont <b>tous</b> venus.')],
        build=[B('every day', ['tous', 'les', 'jours'], 'chaque', 'every + the plural…', '<b>tous les</b> jours.'),
               B('something interesting', ['quelque chose', "d'", 'intéressant'], 'intéressante', 'de + the masculine adjective.', "quelque chose <b>d'</b>intéressant."),
               B('Everyone is here.', ['Tout le monde', 'est', 'là.'], 'sont', 'tout le monde is singular.', 'tout le monde <b>est</b>.'),
               B('Each one has his book.', ['Chacun', 'a', 'son', 'livre.'], 'Chaque', 'On its own: chacun.', '<b>Chacun</b> a…'),
               B('I worked all day.', ["J'ai", 'travaillé', 'toute', 'la', 'journée.'], 'tout', 'journée is feminine.', '<b>toute</b> la journée.')],
        spot=[S(['Chaque', 'élèves', 'a un livre.'], 1, 'élève', 'chaque is always singular.', 'Look at the noun after chaque.'),
              S(['Tout', 'les jours', 'je cours.'], 0, 'Tous', 'jours is plural: <b>tous</b> les jours.', 'Does tout match jours?'),
              S(['Chaque', 'a son livre.'], 0, 'Chacun', 'On its own: <b>chacun</b>.', 'Is there a noun after it?', 'Chacun a son livre.'),
              S(["J'ai vu quelque chose", 'intéressant.'], 1, "d'intéressant.", "quelque chose <b>d'</b>intéressant.", 'Something is missing before the adjective.'),
              S(['Tout le monde', 'sont', 'là.'], 1, 'est', 'tout le monde is singular: <b>est</b>.', 'Singular or plural?')]),
    drill=[['every day (tout)', 'tous les jours', 'jours is plural: <b>tous</b> les jours.'], ['something interesting', "quelque chose d'intéressant", "<b>de</b> + adjective: d'intéressant."],
           ['Everyone is here', 'Tout le monde est là. / Tout le monde est ici.', 'tout le monde is singular: <b>est</b>.'], ['Each one has his book (chacun)', 'Chacun a son livre.', 'On its own: <b>chacun</b>.'],
           ['all night', 'toute la nuit', 'nuit is feminine: <b>toute</b>.'], ['They all came.', 'Ils sont tous venus.', 'all of them: <b>tous</b> (the s is heard).']])

